package javacore2;

public class doublsum {
	
	void add(int a, int b)
	{
		System.out.println(a+b);
	}
	void add(double a, double b)
	{
		System.out.println(a+b);
	}

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		doublsum s=new doublsum();
		s.add(55, 60);
		s.add(70, 80);

	}

}
